const prep = $('Preparar Búsqueda').first().json;
const res = $input.first().json || {};

let ia = null;
try {
  const msg = (res.output || []).find(o => o.type === 'message');
  ia = JSON.parse(msg.content.find(c => c.type === 'output_text').text);
} catch (e) { ia = null; }

const fallo = (reason) => [{ json: { ...prep, valido: false, guardar: false, reason, ia } }];
if (!ia) return fallo('La búsqueda con IA no devolvió un resultado legible' + (res.error ? ': ' + JSON.stringify(res.error).slice(0, 200) : ''));
if (!ia.found) return fallo('La IA no encontró un canal oficial: ' + (ia.notes || '').slice(0, 300));

// Sin new URL(): no está disponible en el entorno de código de este n8n
const host = (u) => { const m = String(u || '').trim().match(/^(?:[a-z]+:\/\/)?([^\/?#:@\s]+)/i); return m ? m[1].toLowerCase() : ''; };
// Nombre de marca del dominio: iberia.com -> iberia, clientes.vodafone.es -> vodafone, x.com.es -> x
const marca = (dominio) => {
  const p = String(dominio || '').toLowerCase().replace(/^www\./, '').split('.').filter(Boolean);
  if (p.length < 2) return '';
  const dobles = ['com', 'org', 'net', 'gob', 'co', 'edu'];
  return (p.length >= 3 && dobles.includes(p[p.length - 2])) ? p[p.length - 3] : p[p.length - 2];
};
const GRATUITOS = ['gmail', 'hotmail', 'outlook', 'yahoo', 'icloud', 'live', 'msn', 'aol', 'protonmail', 'gmx', 'yandex', 'mail'];

const sitio = host(ia.website);
const fuente = host(ia.sourceUrl);
const marcaOficial = marca(sitio);
if (!sitio || !marcaOficial) return fallo('Sin web oficial identificable');
if (!fuente || (marca(fuente) !== marcaOficial)) return fallo('La fuente citada no es la web oficial de la empresa (' + (fuente || 'sin fuente') + ')');
const confianza = Number(ia.confidence) || 0;
if (confianza < 70) return fallo('Confianza insuficiente (' + confianza + ')');

const email = String(ia.email || '').trim().toLowerCase();
const emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
const marcaEmail = emailOk ? marca(email.split('@')[1]) : '';
const mismaMarca = marcaEmail === marcaOficial;
const marcaRelacionada = marcaEmail.length >= 4 && marcaOficial.length >= 4 && (marcaEmail.includes(marcaOficial) || marcaOficial.includes(marcaEmail));
let emailValido = emailOk && !GRATUITOS.includes(marcaEmail) && (mismaMarca || marcaRelacionada);

// Comprobación automática (sustituye a la revisión humana): el email debe aparecer en la página oficial citada
let verificadoEnFuente = null; // true = aparece, false = la página se leyó y no aparece, null = no se pudo leer
if (ia.channel === 'email' && emailValido) {
  try {
    const html = await this.helpers.httpRequest({ method: 'GET', url: /^https?:\/\//i.test(ia.sourceUrl) ? ia.sourceUrl : 'https://' + ia.sourceUrl, timeout: 15000, headers: { 'User-Agent': 'Mozilla/5.0 (PorTusDerechos verificador de canal)' } });
    const texto = String(typeof html === 'string' ? html : JSON.stringify(html)).toLowerCase().replace(/&#64;|&#x40;|\[at\]|\(at\)/g, '@');
    verificadoEnFuente = texto.length > 500 ? texto.includes(email) : null;
  } catch (e) { verificadoEnFuente = null; }
  if (verificadoEnFuente === false) emailValido = false;
  // Dominio de marca distinta (p. ej. endesaonline.com) solo si se ha visto en la web oficial
  if (!mismaMarca && verificadoEnFuente !== true) emailValido = false;
  // Si la página no se pudo leer, solo se acepta con confianza muy alta
  if (verificadoEnFuente === null && confianza < 90) emailValido = false;
}

if (ia.channel === 'email' && !emailValido) {
  const motivo = verificadoEnFuente === false ? 'no aparece en la página oficial citada' : 'no se ha podido verificar en la web oficial ' + sitio;
  return fallo('El email propuesto (' + (email || 'vacío') + ') ' + motivo);
}

const normalizar = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/\b(s\.?\s?a\.?\s?u?\.?|s\.?\s?l\.?\s?u?\.?|sociedad an[oó]nima|sociedad limitada|slu|sau|ltd|inc|gmbh|plc)\b/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ').trim();
const alias = [...new Set([normalizar(ia.legalName), marcaOficial].filter(a => a && a !== prep.normalized))];

const fila = {
  normalized_name: prep.normalized,
  display_name: prep.companyName,
  legal_name: ia.legalName || null,
  aliases: alias,
  website: 'https://' + sitio,
  email: emailValido ? email : null,
  channel: ia.channel,
  form_url: ia.formUrl || null,
  postal_address: ia.postalAddress || null,
  source_url: ia.sourceUrl,
  confidence: verificadoEnFuente === true ? Math.max(confianza, 95) : confianza,
  found_by: 'ai',
  last_verified_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
};
return [{ json: { ...prep, valido: true, guardar: true, fila, ia } }];

const leer = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const prep = leer('Preparar Búsqueda') || {};
if (!prep.ok) return [{ json: { success: false, found: false, error: prep.error || 'Entrada no válida' } }];

const dir = leer('Buscar en Directorio');
const val = leer('Validar Resultado IA');
const base = { success: true, companyName: prep.companyName, caseId: prep.caseId };

if (dir && dir.enDirectorio) {
  const e = dir.entry;
  return [{ json: { ...base, found: true, source: 'directorio', email: e.email || '', channel: e.channel, formUrl: e.form_url || '', website: e.website || '', sourceUrl: e.source_url || '', confidence: e.confidence } }];
}
if (val && val.valido) {
  const f = val.fila;
  return [{ json: { ...base, found: true, source: 'ia', email: f.email || '', channel: f.channel, formUrl: f.form_url || '', website: f.website, sourceUrl: f.source_url, confidence: f.confidence } }];
}
return [{ json: { ...base, found: false, source: 'ninguno', email: '', channel: '', reason: (val && val.reason) || 'Sin resultado' } }];

// Entrada: { companyName, category, caseId }. Solo se llama desde otros workflows (PTD-03), sin webhook público.
const d = $input.first().json || {};
const companyName = String(d.companyName || '').trim().slice(0, 160);
if (companyName.length < 2) return [{ json: { ok: false, error: 'Falta el nombre de la empresa' } }];

// Clave del directorio: sin tildes, sin forma jurídica ni signos
const normalizar = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
  .replace(/\b(s\.?\s?a\.?\s?u?\.?|s\.?\s?l\.?\s?u?\.?|sociedad an[oó]nima|sociedad limitada|slu|sau|ltd|inc|gmbh|plc)\b/g, ' ')
  .replace(/[^a-z0-9]+/g, ' ').trim();

return [{ json: {
  ok: true,
  companyName,
  normalized: normalizar(companyName),
  category: String(d.category || '').slice(0, 60),
  caseId: d.caseId || null
} }];

const prep = $('Preparar Búsqueda').first().json;
const filas = $input.all().map(i => i.json).filter(r => r && r.normalized_name);
const entry = filas.find(r => r.normalized_name === prep.normalized || (r.aliases || []).includes(prep.normalized));
const usable = Boolean(entry && (entry.email || entry.channel !== 'email'));
return [{ json: { ...prep, enDirectorio: usable, entry: usable ? entry : null } }];

